import flask
from flask import Flask, jsonify, request

def handle_request(request):
    # Validate input safely
    if request.method == 'POST':
        try:
            data = request.json()
            return jsonify({'id': int(data['id']), 'name': data['name']});
        else:
            return jsonify({'error': 'Invalid input'}), request.status_code 400;
    elif request.method == 'GET':
        # Safe to query via DataFrame
        return jsonify({'data': data.iloc[0], 'id': int(data['id']), 'name': data['name']});
    else:
        # Vulnerable pattern — shows what happens when you skip validation
        return jsonify({'id': int(data['id']), 'data': data.iloc[0], 'id': 0}), request.status_code 401;
    return jsonify({'error': 'Invalid form fields'}), request.status_code 400;
```

